TOKEN = "fixture-token"


def _body(b) -> bytes:
    if isinstance(b, dict) and "raw" in b:
        return b["raw"].encode()
    if isinstance(b, dict) and "repeat" in b:   # {prefix?, repeat: [text, n], suffix?}: a big body kept small in the file
        return b.get("prefix", "").encode() + b["repeat"][0].encode() * b["repeat"][1] + b.get("suffix", "").encode()
    return json.dumps(b).encode()


class Upstream:
    """Canned answers by request target; records what was asked. A route is {status, body} or {fail: URLError|TimeoutError}."""

    def __init__(self, routes, default=None, strip="", fixed=None):
        self.routes, self.default, self.strip, self.fixed, self.seen = routes, default or {"status": 404, "body": {}}, strip, fixed, []

    def __call__(self, req, timeout, ctx=None):
        target = req.selector   # the request target urllib sends
        self.seen.append({"method": req.get_method(), "target": target, "accept": req.get_header("Accept"),
                          "authorization": req.get_header("Authorization")})
        route = self.routes.get(target, self.default)
        if route.get("fail") == "TimeoutError":
            raise TimeoutError("timed out")
        if route.get("fail"):
            raise urllib.error.URLError("refused")
        return route["status"], _body(route["body"])


def _compact(v):
    """A long run of one character (a body cut at its cap) is written {"$str": [before, char, n, after]}, so the files stay small."""
    if isinstance(v, str) and len(v) > 2000:
        i = 0
        while i < len(v):
            j = i
            while j < len(v) and v[j] == v[i]:
                j += 1
            if j - i >= 1000:
                return {"$str": [v[:i], v[i], j - i, v[j:]]}
            i = j
    if isinstance(v, dict):
        return {k: _compact(x) for k, x in v.items()}
    if isinstance(v, list):
        return [_compact(x) for x in v]
    return v


def _outcome(fn) -> dict:
    try:
        return {"result": _compact(fn())}
    except Denied as e:
        return {"denied": {"rule": e.rule, "message": e.message, "hint": e.hint}}
    except Exception as e:  # noqa: BLE001
        return {"error": {"class": type(e).__name__, "outcome_result": dispatch._error_result(e),
                          "agent_error": dispatch._backend_error(e)}}


def _case(name, kind, up, outcome, **extra) -> dict:
    return {"name": name, "kind": kind, "routes": up.routes, "default": up.default, "requests": up.seen, **outcome, **extra}


def _go_echo(v) -> str:
    """What Go repeats of an argument in a refusal: repr, cut to 100 characters (Python repeats it whole)."""
    if isinstance(v, str):
        return repr(v[:100]) + "..." if len(v) > 100 else repr(v)
    r = repr(v)
    return r[:100] + "..." if len(r) > 100 else r


def _clipped(outc: dict, arg, extra: dict) -> None:
    """When the refusal repeats an argument longer than Go repeats, Go's expectation is the same refusal with the cut text."""
    d = outc.get("denied")
    if d and _go_echo(arg) != repr(arg) and d["message"].startswith(repr(arg)):
        extra["go"] = {"denied": {**d, "message": _go_echo(arg) + d["message"][len(repr(arg)):]}, "requests": []}
        extra["why"] = "Go repeats at most 100 characters of the argument in a refusal; Python repeats it whole"


