    return {"kind": "Component", "metadata": {"namespace": "default", "name": "gate-api", "title": "Gate API", "description": "gates",
                                              "annotations": {"secret-ish": "x"}},
            "spec": {"type": "service", "owner": "group:default/skyport", "lifecycle": "production", "values": {"k": 1}}, **kw}


