    tok.write_text(TOKEN + "\n")
    many = [{"kind": "Component", "metadata": {"name": f"c{i}"}} for i in range(30)]
    cases = [
        ("a full-text search", "gate", 200, {"items": [_entity()], "totalItems": 1, "pageInfo": {}}),
        ("a filter", "kind=component,spec.owner=group:default/skyport", 200, {"items": [_entity()], "totalItems": 1, "pageInfo": {}}),
        ("a query with specials", "a b&c=d#e+f%g/é", 200, {"items": [], "totalItems": 0}),
        ("a text query with specials", "a b&c#e+f%g/é", 200, {"items": []}),
        ("a padded query", "  gate  ", 200, {"items": []}),
        ("a filter with padding", "  kind=component  ", 200, {"items": []}),
        ("more than 25 entities", "x", 200, {"items": many, "totalItems": 30}),
        ("a next cursor", "x", 200, {"items": [], "pageInfo": {"nextCursor": "abc"}}),
        ("an empty next cursor", "x", 200, {"items": [], "pageInfo": {"nextCursor": ""}}),
        ("odd entities", "x", 200, {"items": [
            {"kind": None, "metadata": {"namespace": None, "name": None}}, {"metadata": {"name": "n"}}, {},
            {"kind": "API", "metadata": {"name": "a", "description": "d" * 600, "title": "t"}, "spec": {"system": "s", "type": None}},
            {"kind": "Group", "metadata": {"namespace": "ns", "name": 7}, "spec": {"owner": ["a"], "lifecycle": 1.5}},
            {"kind": "Ünï", "metadata": {"name": "é"}}]}),
        ("no items", "x", 200, {}),
        ("items null", "x", 200, {"items": None, "totalItems": 3}),
        ("items an object", "x", 200, {"items": {"a": 1}}),
        ("items a string", "x", 200, {"items": "abc"}),
        ("items a number", "x", 200, {"items": 5}),
        ("an entity that is not an object", "x", 200, {"items": [1]}),
        ("an answer that is a list", "x", 200, [1, 2]),
        ("an answer that is not JSON", "x", 200, {"raw": "<html>"}),
        ("an empty answer", "x", 200, {"raw": ""}),
        ("JSON then more", "x", 200, {"raw": "{} {}"}),
        ("refused identity 401", "x", 401, {"error": "no"}),
        ("refused identity 403", "x", 403, {"raw": "secret-body"}),
        ("a bad query", "kind=", 400, {"raw": "Invalid filter: " + "é" * 600}),
        ("a bad query, short", "kind=", 400, {"raw": "bad"}),
        ("a bad query, empty", "kind=", 400, {"raw": ""}),
        ("server error", "x", 500, {"raw": "boom"}),
        ("a redirect is an error status", "x", 302, {"raw": ""}),
        ("not found", "x", 404, {}),
    ]
    for name, query, status, body in cases:
        up = Upstream({}, default={"status": status, "body": body})
        c = reads.BackstageCatalog("http://backstage.test/", tok, opener=up)
        out.append(_case(name, "catalog", up, _outcome(lambda: c.catalog(query)), args={"query": query}, token=TOKEN))
    for name, query in (("an empty query", ""), ("a blank query", " \t\n"), ("a long query", "x" * 501), ("a query of 500", "x" * 500),
                        ("a non-string query", 5), ("a null query", None), ("a list query", ["a"]),
                        ("a unit-separator query", "\x1f"), ("a no-break-space query", "\xa0")):
        up = Upstream({}, default={"status": 200, "body": {"items": []}})
        c = reads.BackstageCatalog("http://backstage.test", tok, opener=up)
        out.append(_case(name, "catalog", up, _outcome(lambda: c.catalog(query)), args={"query": query}, token=TOKEN))
    for name, fail in (("unreachable", "URLError"), ("a timeout", "TimeoutError")):
        up = Upstream({}, default={"fail": fail})
        c = reads.BackstageCatalog("http://backstage.test", tok, opener=up)
        out.append(_case(name, "catalog", up, _outcome(lambda: c.catalog("x")), args={"query": "x"}, token=TOKEN))
    up = Upstream({}, default={"status": 200, "body": {"items": []}})
    c = reads.BackstageCatalog("http://backstage.test/prefix/", tok, opener=up)
    out.append(_case("a base with a path", "catalog", up, _outcome(lambda: c.catalog("x")), args={"query": "x"}, token=TOKEN,
                     base_path="/prefix"))
    up = Upstream({}, default={"status": 200, "body": {"items": []}})
    c = reads.BackstageCatalog("http://backstage.test", tmp / "absent", opener=up)
    out.append(_case("no token file", "catalog", up, _outcome(lambda: c.catalog("x")), args={"query": "x"}, token=None))
