def _apis(up, base="http://flight-api.app.svc:8080/"):
    return reads.AppAPIs({"flight-api": base, "baggage-api": "https://baggage.app.svc/v2"}, opener=up)


GO_STRICTER = {
    "/a\n": ("a newline at the end: Python's $ matches before it (its HTTP client then refuses the URL, a ValueError "
             "that is no BackendError); Go refuses the path"),
    "/a%0d%0ab": "an encoded CR LF: Python sends it encoded; Go refuses an encoded control character",
    "/a%0Ab": "an encoded LF: Python sends it encoded; Go refuses an encoded control character",
    "/a%7f": "an encoded DEL: Python sends it; Go refuses it",
    "/a%2": "a % without two hex digits: Python sends it; Go refuses it",
    "/a%zz": "a % without two hex digits: Python sends it; Go refuses it",
    "/a%": "a lone %: Python sends it; Go refuses it",
    "/..%3b/admin": "an encoded ; after dots: a server that decodes first reads ..;/ and strips it to a dot segment; Go decides on the decoded segment",
    "/.%3b/": "an encoded ; after a dot (decoded segment .;): refused on the decoded form",
    "/a/..%3B/x": "an encoded ; after dots, upper case: refused on the decoded form",
    "/%c0%ae%c0%ae/admin": "an overlong encoding of dots: Go refuses any decoded byte outside printable ASCII",
    "/%C0%AE%c0%Ae/admin": "an overlong encoding of dots, mixed case: refused",
    "/%c0%af": "an overlong encoding of a slash: refused",
    "/%C0%AF": "an overlong encoding of a slash, upper case: refused",
    "/%ef%bc%8f": "a fullwidth slash (U+FF0F): refused",
    "/%EF%BC%8F": "a fullwidth slash, upper case: refused",
    "/%ef%bc%8e%ef%bc%8e/x": "fullwidth dots (U+FF0E): refused",
    "/%e2%88%95": "a division slash (U+2215): refused",
    "/%e2%81%84": "a fraction slash (U+2044): refused",
    "/%e2%80%a4": "a one-dot leader (U+2024): refused",
    "/caf%c3%a9": "well-formed UTF-8 is still non-ASCII: Go refuses any decoded byte outside printable ASCII in the path (real application paths are ASCII)",
    "/%ff": "invalid UTF-8: refused",
    "/%80": "a lone continuation byte: refused",
    "/a%3fb": "an encoded ? in the path: refused",
    "/a%23b": "an encoded # in the path: refused",
    "/a/..;/b": "a dot segment before a ;: Python sends it; Go refuses it",
    "/a/.;/b": "a dot segment before a ;: Python sends it; Go refuses it",
}


def appapi_cases() -> list:
    out = []
    ok_paths = ["/api/flights?date=2026-11-03", "/", "/health", "/a/b/c.json", "/a?x=1&y=%20z", "/a?next=a/b?c", "/a;b=c/d",
                "/a@b/c", "/a:b", "/~u/%7Euser", "/a%20b", "/q?", "/" + "a" * 511, "/a?x=" + "b" * 100]
    bad_paths = ["api/flights", "//evil.test/x", "/a//b", "/a/../b", "/..", "/.", "/a/./b", "/a/%2e%2e/b", "/a/%2E/b", "/a%2fb", "/a%2Fb",
                 "/a/%252e%252e/b", "/a%252fb", "http://evil.test/", "https://evil.test/", "/a#frag", "#x", "/a b", "/" + "a" * 600,
                 "/a\\b", "/a%5cb", "/a%5Cb", "/a%00", "/a\x00b", "/a\rb", "/a\r\nHost: evil", "", "?x=1", "/a?x=http://e/", "/a?x=//e",
                 "/é", "/a|b", "/a<b", '/a"b', "/a{b}", "@evil.test/x", "/@evil.test:80/../x", "/.%2e/x", "/%2e./x"]
    for path in ok_paths + [p for p in GO_STRICTER if p not in ok_paths]:
        up = Upstream({}, default={"status": 200, "body": {"flights": []}})
        outc = _outcome(lambda: _apis(up).get("flight-api", path))
        extra = {}
        if path in GO_STRICTER:
            extra["go"] = {"denied": {"rule": "READ-API-PATH", "message": f"{path[:80]!r} is not a path on the service",
                                      "hint": "Pass an absolute path such as /api/flights?date=2026-11-03 (no host, no '..')."},
                           "requests": []}
            extra["why"] = GO_STRICTER[path]
        out.append(_case("path " + repr(path)[:60], "appapi", up, outc, args={"service": "flight-api", "path": path}, **extra))
    for path in bad_paths + [None, 5, 1.5, True, ["/a"], {"a": 1}, "é" * 3]:
        up = Upstream({}, default={"status": 200, "body": {}})
        out.append(_case("refused path " + repr(path)[:60], "appapi", up, _outcome(lambda: _apis(up).get("flight-api", path)),
                         args={"service": "flight-api", "path": path}))
    for svc in ("baggage-api", "baggage-api\n", "Flight-API", "../x", "", None, 5, ["flight-api"], "x" * 70, "it's", 'say "hi"\'', "é\t", "y" * 100, "y" * 101, "z" * 300, [1] * 60):
        up = Upstream({}, default={"status": 200, "body": {}})
        oc = _outcome(lambda: _apis(up).get(svc, "/x"))
        extra = {}
        _clipped(oc, svc, extra)
        out.append(_case("service " + repr(svc)[:40], "appapi", up, oc, args={"service": svc, "path": "/x"}, **extra))
    answers = [("json", 200, {"flights": [1, 2.5, None, True, "é"], "n": 10 ** 20}), ("a json list", 200, [1, 2]), ("a json null", 200, {"raw": "null"}),
               ("a json false", 200, {"raw": "false"}), ("a json zero", 200, {"raw": "0"}), ("a json string", 200, {"raw": '"x"'}),
               ("text", 503, {"raw": "upstream down"}), ("empty", 204, {"raw": ""}), ("not found json", 404, {"error": "no"}),
               ("a redirect", 302, {"raw": "moved"}), ("a big body", 200, {"repeat": ["x", reads.MAX_API_BODY + 10]}),
               ("exactly the cap", 200, {"repeat": ["x", reads.MAX_API_BODY]}),
               ("a big json body", 200, {"prefix": '{"a": "', "repeat": ["x", reads.MAX_API_BODY + 5], "suffix": '"}'}),
               ("json padded", 200, {"raw": '  {"a": 1}  \n'}), ("two json values", 200, {"raw": "{} {}"}),
               ("a deep json", 200, {"raw": "[" * 400 + "]" * 400}), ("json with a duplicate key", 200, {"raw": '{"a": 1, "a": 2}'})]
    for name, status, body in answers:
        up = Upstream({}, default={"status": status, "body": body})
        extra = {}
        if name == "a deep json":
            extra = {"go": {"result": {"service": "flight-api", "path": "/x", "status": 200, "truncated": False,
                                       "text": "[" * 400 + "]" * 400}, "requests": None}, "why": "JSON nested past 256 levels is text, not decoded"}
        out.append(_case("answer: " + name, "appapi", up, _outcome(lambda: _apis(up).get("flight-api", "/x")),
                         args={"service": "flight-api", "path": "/x"}, **extra))
    for name, fail in (("unreachable", "URLError"), ("a timeout", "TimeoutError")):
        up = Upstream({}, default={"fail": fail})
        out.append(_case(name, "appapi", up, _outcome(lambda: _apis(up).get("flight-api", "/x")), args={"service": "flight-api", "path": "/x"}))
    up = Upstream({}, default={"status": 200, "body": {}})
    out.append(_case("a service with a base path", "appapi", up, _outcome(lambda: _apis(up).get("baggage-api", "/a/b?c=d")),
                     args={"service": "baggage-api", "path": "/a/b?c=d"}, base_path="/v2"))
    return out


