P = "/apis/argoproj.io/v1alpha1/namespaces/{ns}/applications"


def _labelled(name, ns, env=None, role="tenant-onboarding", health="Healthy"):
    labels = {"hangar.io/app": "flight-api", "hangar.io/subcomponent": role, **({"hangar.io/env": env} if env else {})}
    return {"metadata": {"name": name, "namespace": ns, "labels": labels}, "spec": {"project": "flight-api"},
            "status": {"sync": {"status": "Synced"}, "health": {"status": health}}}


LIST = P + "?labelSelector=hangar.io%2Fapp%3D{app}&limit=500"


def argo_cases() -> list:
    out = []
    tmp = Path(tempfile.mkdtemp())
    tok = tmp / "token"
    tok.write_text(TOKEN + "\n")

    def run(name, app, routes, namespaces=("argocd", "argocd-apps"), default=None, **extra):
        up = Upstream(routes, default=default, strip="https://api")
        a = reads.KubeArgo(KubeReader("https://api", tok, None, opener=up), namespaces)
        oc = _outcome(lambda: a.get_app(app))
        if "go" not in extra:
            _clipped(oc, app, extra)
        res = oc.get("result")
        if isinstance(res, dict) and any(re.match(r"^[A-Za-z][A-Za-z0-9+.-]*://[^/?#]*@", x.get("repoURL") or "") for x in res.get("sources") or []):
            go = json.loads(json.dumps(res))
            for x in go["sources"]:
                if isinstance(x.get("repoURL"), str):
                    x["repoURL"] = re.sub(r"^([A-Za-z][A-Za-z0-9+.-]*://)[^/?#]*@", r"\1", x["repoURL"])
            extra["go"] = {"result": go}
            extra["why"] = "Go removes credentials (user:token@) from every repoURL; Python returns it as it is"
        out.append(_case(name, "argo", up, oc, args={"app": app}, namespaces=list(namespaces), token=TOKEN, **extra))

    def r(status, body):
        return {"status": status, "body": body}
    g = P.format(ns="argocd") + "/flight-api-dev"
    run("a summary without the helm values", "flight-api-dev", {g: r(200, APP)})
    run("a second namespace", "boarding-api", {P.format(ns="argocd-apps") + "/boarding-api": r(200, {**APP, "metadata": {"name": "boarding-api", "namespace": "argocd-apps"}})})
    run("an app with sources", "multi", {P.format(ns="argocd") + "/multi": r(200, {"metadata": {"name": "multi"}, "spec": {"sources": [
        {"repoURL": "r1", "chart": "c", "helm": {"x": 1}}, {"path": "p", "ref": "vals"}, {}], "source": {"repoURL": "ignored"}}})})
    run("repo URLs with credentials", "creds", {P.format(ns="argocd") + "/creds": r(200, {"metadata": {"name": "creds"}, "spec": {"sources": [
        {"repoURL": "https://user:ghp_SECRET@github.com/o/r.git", "path": "a"}, {"repoURL": "https://tok@host:8443/o/r", "chart": "c"},
        {"repoURL": "ssh://git:pw@host/o/r"}, {"repoURL": "git@github.com:o/r.git"}, {"repoURL": "https://github.com/o/r?x=a@b"},
        {"repoURL": "https://u:p@a@host/r"}, {"repoURL": None}, {"repoURL": 5}, {"path": "p"}]}})})
    run("an empty app", "empty", {P.format(ns="argocd") + "/empty": r(200, {})})
    run("an app with nulls", "nulls", {P.format(ns="argocd") + "/nulls": r(200, {"metadata": None, "spec": None, "status": {
        "sync": None, "health": None, "operationState": {}, "conditions": None, "resources": None}})})
    many = [{"kind": "K", "name": f"r{i}", "namespace": "n", "status": "OutOfSync"} for i in range(60)]
    run("more than 50 unhealthy resources", "big", {P.format(ns="argocd") + "/big": r(200, {"metadata": {"name": "big"}, "status": {"resources": many}})})
    run("not found anywhere", "nope", {})
    run("not found, a name that is no label value", "a" * 70, {})
    items = [_labelled("flight-api-xr-requests", "argocd-apps", role="xr-requests"), _labelled("flight-api-dev", "argocd-apps", env="dev", health="Degraded"),
             _labelled("flight-api-prod", "argocd-apps", env="prod"), _labelled("flight-api-onboarding", "argocd-apps")]
    run("an app name resolves by label", "flight-api", {LIST.format(ns="argocd", app="flight-api"): r(200, {"items": []}),
                                                      LIST.format(ns="argocd-apps", app="flight-api"): r(200, {"items": items})})
    run("sixty labelled apps", "flight-api", {LIST.format(ns="argocd", app="flight-api"): r(200, {"items": [
        _labelled(f"flight-api-e{i:02d}", "argocd", env=f"e{i:02d}") for i in range(60)]})})
    cont = LIST.format(ns="argocd", app="flight-api")
    run("a list that continues", "flight-api", {cont: r(200, {"items": [_labelled("a-1", "argocd", env="x")], "metadata": {"continue": "tok/+="}}),
                                                cont + "&continue=tok%2F%2B%3D": r(200, {"items": [_labelled("a-2", "argocd", env="y")]})},
        namespaces=("argocd",))
    run("a list that never ends", "flight-api", {cont: r(200, {"items": [], "metadata": {"continue": "c"}}),
                                                 cont + "&continue=c": r(200, {"items": [], "metadata": {"continue": "c"}})}, namespaces=("argocd",))
    run("a list gone mid-way", "flight-api", {cont: r(200, {"items": [_labelled("a-1", "argocd", env="x")], "metadata": {"continue": "c"}})},
        namespaces=("argocd",))
    run("one namespace", "x", {}, namespaces=("argocd",))
    run("identity refused 403", "x", {}, default=r(403, {"raw": "forbidden"}))
    run("identity refused 401", "x", {}, default=r(401, {"raw": "unauthorized"}))
    run("server error", "x", {}, default=r(500, {"raw": "token-in-body"}))
    run("a redirect", "x", {}, default=r(302, {"raw": ""}))
    run("an answer that is not JSON", "x", {}, default=r(200, {"raw": "<html>"}))
    run("an empty answer", "x", {}, default=r(200, {"raw": ""}))
    run("a list that is not JSON", "flight-api", {P.format(ns="argocd") + "/flight-api": r(404, {}), cont: r(200, {"raw": "no"})}, namespaces=("argocd",))
    run("unreachable", "x", {}, default={"fail": "URLError"})
    run("a timeout", "x", {}, default={"fail": "TimeoutError"})
    for app in ("../secrets", "Flight", "a/b", "", "x" * 300, "x" * 254, "a" * 253, "-a", "a-", "a.b", "a..b", "a_b", "flight-api\n", "é", None, 5,
                ["x"], {"a": 1}, True, 1.5, "it's", 'q"q\'', "a\\b", "a\tb\x00", "%2e", "a%2fb", "a b"):
        extra = {}
        if app == "flight-api\n":
            extra = {"go": {"denied": {"rule": "READ-ARGO-NAME", "message": "'flight-api\\n' is not an Application name",
                                       "hint": "Pass the Argo CD Application's name (e.g. flight-api-dev) or an app's catalog component name (e.g. flight-api)."},
                            "requests": []},
                     "why": "Python's $ matches before a trailing newline (and then its path allowlist refuses, AF-K8S-PATH); Go refuses the name"}
        run("name " + repr(app)[:40], app, {}, **extra)
    return out


def reads_cases() -> str:
    doc = {"token": TOKEN, "cases": catalog_cases() + appapi_cases() + argo_cases()}
    return json.dumps(doc, indent=1, sort_keys=True) + "\n"


# -- artifacts --------------------------------------------------------------------------------------------------------

class _Cur:
    """Just enough of a psycopg cursor for PgArtifacts' four statements, over a dict."""

    def __init__(self, rows):
        self.rows, self._res = rows, None

    def __enter__(self):
        return self

    def __exit__(self, *a):
        return False

    def execute(self, sql, params=()):
        s = " ".join(sql.split())
        if s.startswith("DELETE FROM gateway_artifacts WHERE expires_at"):
            for k in [k for k, v in self.rows.items() if v["expires_at"] <= params[0]]:
                del self.rows[k]
        elif s.startswith("SELECT count(*)"):
            mine = [v for (t, n), v in self.rows.items() if t == params[0] and n != params[1]]
            self._res = (len(mine), sum(v["bytes"] for v in mine))
        elif s.startswith("INSERT INTO gateway_artifacts"):
            task, name, content, size, exp = params
            self.rows[(task, name)] = {"content": content, "bytes": size, "expires_at": exp}
        elif s.startswith("SELECT content"):
            task, name, now = params
            v = self.rows.get((task, name))
            self._res = (v["content"],) if v and v["expires_at"] > now else None
        else:
            raise AssertionError(s)

    def fetchone(self):
        return self._res


class _State:
    def __init__(self):
        self.rows = {}
        self.conn = self

    def cursor(self):
        return _Cur(self.rows)


T0 = datetime(2026, 11, 14, 12, 0, 0, tzinfo=timezone.utc)


def artifact_cases() -> str:
    clock = [T0]
    store = pg.PgArtifacts(_State(), now=lambda: clock[0])
    ops = []

    def op(kind, task, name=None, content=None, at=0, micro=0, **extra):
        clock[0] = T0 + timedelta(seconds=at, microseconds=micro)
        if kind == "put":
            out = _outcome(lambda: store.put(task, name, content))
        else:
            out = _outcome(lambda: {"content": store.get(task, name)})
        shown = _compact(content)
        if kind == "put" and "go" not in extra:
            _clipped(out, name, extra)
        ops.append({"op": kind, "task": task, "name": name, "content": shown, "at": at, "micro": micro, **out, **extra})

    # names and contents
    op("put", "t-1", "plan.md", "hello")
    op("get", "t-1", "plan.md")
    op("put", "t-1", "plan.md", "replaced é", at=5)
    op("get", "t-1", "plan.md", at=6)
    op("put", "t-1", "micro", "x", at=1, micro=123456)
    op("put", "t-1", "micro-zero", "x", at=2)
    for bad in ("", "a b", "a/b", "../x", ".", "..", "x" * 101, "é", None, 5, ["a"], "a\x00b", "a,b", "it's", "n" * 400, "a b" * 50):
        op("put", "t-1", bad, "x")
    op("put", "t-1", "x" * 100, "ok")
    op("put", "t-1", "trailing-newline\n", "x", go={"denied": {"rule": "ART-NAME", "message": "'trailing-newline\\n' is not an artifact name",
                                                             "hint": "Use letters, digits, '.', '_' or '-'."}},
       why="Python's $ matches before a trailing newline; Go refuses the name")
    for bad in (5, None, {"a": 1}, ["x"], 1.5, True):
        op("put", "t-1", "c", bad)
    op("put", "t-1", "nul", "a\x00b", go={"denied": {"rule": "ART-CONTENT", "message": "an artifact's content is text",
                                                      "hint": "Pass a string without a NUL character (JSON-encode structured data)."}},
       why="Python hands the NUL to the database driver, which fails the call; Go refuses the content")
    op("put", "t-1", "max", "a" * (256 << 10))
    op("put", "t-1", "over", "a" * ((256 << 10) + 1))
    op("put", "t-1", "overwide", "é" * ((128 << 10) + 1))
    op("put", "t-1", "wide", "é" * (128 << 10))
    op("get", "t-1", "max")
    # the task is the key
    op("put", "t-2", "plan.md", "other task")
    op("get", "t-2", "plan.md")
    op("get", "t-3", "plan.md")
    op("get", "", "plan.md")
    op("get", "t-1", "missing")
    for bad in ("", "a b", "../x", None, 5, "x" * 101):
        op("get", "t-1", bad)
    # quota: 32 artifacts, then a replacement is fine and a new name is not
    for i in range(32):
        op("put", "t-q", f"n{i:02d}", "x", at=10)
    op("put", "t-q", "n32", "x", at=10)
    op("put", "t-q", "n00", "replaced", at=10)
    op("get", "t-q", "n00", at=10)
    # quota: bytes
    for i in range(8):
        op("put", "t-b", f"b{i}", "a" * (256 << 10), at=10)
    op("put", "t-b", "b8", "a", at=10)
    op("put", "t-b", "b0", "a" * (256 << 10), at=10)
    op("put", "t-b", "b0", "a" * 10, at=10)
    op("put", "t-b", "b8", "a" * (256 << 10), at=10)
    # expiry: seven days after the last write
    day = 86400
    op("get", "t-1", "plan.md", at=6 + 7 * day - 1)
    op("get", "t-1", "plan.md", at=6 + 7 * day)
    op("put", "t-e", "e", "x", at=100)
    op("get", "t-e", "e", at=100 + 7 * day - 1)
    op("put", "t-e", "e", "y", at=100 + 3 * day)
    op("get", "t-e", "e", at=100 + 7 * day + 5)
    op("get", "t-e", "e", at=100 + 10 * day + 1)
    # an expired artifact does not count against the quota
    op("put", "t-x", "old", "x", at=1000)
    for i in range(31):
        op("put", "t-x", f"n{i:02d}", "x", at=1000 + 7 * day)
    op("put", "t-x", "last", "x", at=1000 + 7 * day)
    op("put", "t-x", "one-too-many", "x", at=1000 + 7 * day)
    return json.dumps({"start": T0.isoformat(), "ops": ops}, indent=1, sort_keys=True) + "\n"


def outputs() -> dict:
    return {DIR / "reads.json": reads_cases(), DIR / "artifacts.json": artifact_cases()}


if __name__ == "__main__":
    for p, t in outputs().items():
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(t)
